			t.Fatal("recreated archive replay did not catch up")
		}
	}
	result := reader.Range(observability.HistoryQuery{Metric: observability.HistHostCPUUtilization,
		Labels: map[string]string{"member": "host-a"}, Start: start, End: clock})
