		if err != nil {
			return 0
		}
		response.Body.Close()
		return response.StatusCode
	}
	await := func(want int) {
		t.Helper()
		for deadline := time.Now().Add(10 * time.Second); health() != want; {
			if time.Now().After(deadline) {
				t.Fatalf("health %d, want %d", health(), want)
			}
			time.Sleep(20 * time.Millisecond)
		}
