		Replicas: 1, ArtifactSigner: artifactCodec, ArtifactVerifier: artifactCodec,
		AuthorizeArtifact: func(context.Context, string, delivery.ArtifactRecord) error { return nil }})
	if err != nil {
		t.Fatal(err)
	}
