		spec: func() (*cellspec.ReleaseFence, map[string]string) {
			return &cellspec.ReleaseFence{}, map[string]string{"controller": "10.251.0.11"}
		}}, fleet: fleet, managedAddresses: map[string]string{"retired": retired.PrivateIP}}
