		t.Fatalf("record recovery used unrelated inventory or lost adopted peers: addresses=%v selected=%v full=%d", addresses, fleet.selected, fleet.fullCalls)
	}
	pin, err := client.LoadPin("../../deploy/image/image-inputs.json")
	if err != nil {
		t.Fatal(err)
	}
